// CLIENT_ACTION_ID_PREFIX versions the durable client-owned action identity format.
// CLIENT_ACTION_ID_PREFIX 对可靠的客户端所属动作身份格式进行版本化。
const CLIENT_ACTION_ID_PREFIX = "vcn1";

// NOTIFICATION_CLIENT_SESSION_KEY stores one browser-tab or Electron-window identity across reloads.
// NOTIFICATION_CLIENT_SESSION_KEY 跨重载保存一个浏览器标签页或 Electron 窗口身份。
const NOTIFICATION_CLIENT_SESSION_KEY = "vulcan.notifications.client-instance.v1";

// CANONICAL_UUID_PATTERN accepts only lowercase canonical UUID text generated by Web Crypto.
// CANONICAL_UUID_PATTERN 只接受由 Web Crypto 生成的小写规范 UUID 文本。
const CANONICAL_UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

// ClientIdentityStorage is the minimal session-scoped storage contract required by the resolver.
// ClientIdentityStorage 是解析器所需的最小会话级存储契约。
interface ClientIdentityStorage {
  // getItem reads the stored identity or returns null when none exists.
  // getItem 读取已存储身份，不存在时返回 null。
  getItem(key: string): string | null;
  // setItem persists the identity for later reloads of the same client surface.
  // setItem 为同一客户端界面的后续重载持久化身份。
  setItem(key: string, value: string): void;
}

// currentSessionStorage resolves sessionStorage without failing restricted or non-browser runtimes.
// currentSessionStorage 在受限环境或非浏览器运行时中安全解析 sessionStorage。
// The function has no parameters and returns null when session-scoped storage is unavailable.
// 此函数没有参数；会话级存储不可用时返回 null。
function currentSessionStorage(): ClientIdentityStorage | null {
  try {
    return typeof globalThis.sessionStorage === "undefined" ? null : globalThis.sessionStorage;
  } catch {
    return null;
  }
}

// clientRetryStorageKey addresses one pending action under the exact tab or window owner.
// clientRetryStorageKey 按精确的标签页或窗口所有者定位一项待重试操作。
// scope identifies the operation and its immutable inputs; returns its sessionStorage key.
// scope 标识操作及其不可变输入，返回对应的 sessionStorage 键。
function clientRetryStorageKey(scope: string): string {
  return `vulcan.action-retry.v1:${notificationClientInstanceId}:${scope}`;
}

// currentDocumentIsReload distinguishes a real reload from a new tab that copied sessionStorage.
// currentDocumentIsReload 区分真正重载与复制了 sessionStorage 的新标签页。
// Returns true only when the browser reports a reload navigation for this document.
// 仅当浏览器报告本文档属于重载导航时返回 true。
function currentDocumentIsReload(): boolean {
  if (typeof performance === "undefined") return false;
  const navigation = performance.getEntriesByType("navigation")[0] as PerformanceNavigationTiming | undefined;
  return navigation?.type === "reload";
}

// resolveNotificationClientInstanceId restores an actual reload or creates a new page identity.
// resolveNotificationClientInstanceId 在真正重载时恢复身份，否则创建新的页面身份。
// storage is session-scoped, isReload describes this document navigation, and the result is a UUID.
// storage 是会话级存储，isReload 描述本文档导航；返回值是 UUID。
export function resolveNotificationClientInstanceId(
  storage: ClientIdentityStorage | null = currentSessionStorage(),
  isReload: boolean = currentDocumentIsReload(),
): string {
  // Browser duplicate-tab and window.open copy sessionStorage; only a reload may reuse its ID.
  // 浏览器复制标签页和 window.open 会复制 sessionStorage；仅真正重载可复用其中的标识。
  if (storage !== null && isReload) {
    try {
      // storedIdentity preserves ownership when the same client surface reloads during a long run.
      // storedIdentity 在同一客户端界面于长任务期间重载时保留所有权。
      const storedIdentity = storage.getItem(NOTIFICATION_CLIENT_SESSION_KEY);
      if (storedIdentity !== null && CANONICAL_UUID_PATTERN.test(storedIdentity)) {
        return storedIdentity;
      }
    } catch {
      // A storage read failure falls through to a process-local identity without weakening format checks.
      // 存储读取失败时退回进程内身份，同时不放宽格式校验。
    }
  }
  // createdIdentity is owned by this exact loaded client surface.
  // createdIdentity 归当前精确加载的客户端界面所有。
  const createdIdentity = globalThis.crypto.randomUUID();
  if (storage !== null) {
    try {
      storage.setItem(NOTIFICATION_CLIENT_SESSION_KEY, createdIdentity);
    } catch {
      // Notification ownership remains valid for this load even when persistence is unavailable.
      // 即使无法持久化，通知所有权在本次加载期间仍然有效。
    }
  }
  return createdIdentity;
}

// notificationClientInstanceId uniquely identifies this browser tab or Electron window.
// notificationClientInstanceId 唯一标识当前浏览器标签页或 Electron 窗口。
export const notificationClientInstanceId = resolveNotificationClientInstanceId();

// createClientOwnedActionId creates one durable action id that carries its notification owner.
// createClientOwnedActionId 创建一条携带通知所有者的可靠动作标识。
// Returns a bounded client-action id containing the current client id and a unique action id.
// 返回包含当前客户端标识与唯一动作标识的有界客户端动作标识。
export function createClientOwnedActionId(): string {
  // actionId distinguishes retries and independent actions from the same client instance.
  // actionId 区分同一客户端实例发起的重试与独立动作。
  const actionId = globalThis.crypto.randomUUID();
  return `${CLIENT_ACTION_ID_PREFIX}:${notificationClientInstanceId}:${actionId}`;
}

// retainClientOwnedRetryActionId restores or persists the pending action for scope before dispatch.
// retainClientOwnedRetryActionId 在派发前恢复或持久化 scope 对应的待重试操作。
// Returns the exact pending identity, with in-memory retries still available when storage is disabled.
// 返回精确的待重试身份，存储禁用时仍可在内存中重试。
export function retainClientOwnedRetryActionId(scope: string): string {
  // Use the same tab owner as notifications so a copied tab starts a separate operation.
  // 使用与通知相同的标签页所有者，使复制出的标签页发起独立操作。
  const storage = currentSessionStorage();
  // key binds the action to its owner and exact inputs.
  // key 将操作绑定到所有者和精确输入。
  const key = clientRetryStorageKey(scope);
  // prefix is the required owner portion of the generated identity.
  // prefix 是生成身份必须具有的所有者前缀。
  const prefix = `${CLIENT_ACTION_ID_PREFIX}:${notificationClientInstanceId}:`;
  try {
    // previous is valid only if this client owns the stored canonical UUID.
    // previous 仅在当前客户端持有存储的规范 UUID 时有效。
    const previous = storage?.getItem(key);
    if (previous?.startsWith(prefix) && CANONICAL_UUID_PATTERN.test(previous.slice(prefix.length))) {
      return previous;
    }
  } catch {
    // An unavailable session store does not prevent the action from running.
    // 会话存储不可访问时仍可执行操作。
  }
  // actionId is retained before the request can reach the server.
  // actionId 在请求抵达服务端之前保存。
  const actionId = createClientOwnedActionId();
  try {
    storage?.setItem(key, actionId);
  } catch {
    // The caller keeps this ID for retries during the current page load.
    // 调用方保留该 ID，用于当前页面内重试。
  }
  return actionId;
}

// completeClientOwnedRetryAction removes the retained ID for the acknowledged operation.
// completeClientOwnedRetryAction 移除已确认操作的保留 ID。
// scope locates the pending action and actionId protects a newer action from stale acknowledgement.
// scope 定位待重试操作，actionId 防止过期确认清除较新的操作。
export function completeClientOwnedRetryAction(scope: string, actionId: string): void {
  try {
    // The same storage implementation and key own both the pending ID and its removal.
    // 同一个存储实现和键同时管理待重试 ID 及其移除。
    const storage = globalThis.sessionStorage;
    // key identifies the acknowledged operation in the current client.
    // key 标识当前客户端已确认的操作。
    const key = clientRetryStorageKey(scope);
    if (storage?.getItem(key) === actionId) storage.removeItem(key);
  } catch {
    // A storage failure does not change the server acknowledgement.
    // 存储失败不影响服务端确认。
  }
}
